import React, { useState, useEffect } from 'react';
import api from '../services/api';
import Card from '../components/Card';

function Reports() {
  const [stats, setStats] = useState({ total: 0, confirmed: 0, pending: 0, cancelled: 0 });

  useEffect(() => { loadData(); }, []);

  const loadData = async () => {
    try {
      const res = await api.get('/reports.php');
      setStats(res.data || { total: 0, confirmed: 0, pending: 0, cancelled: 0 });
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div style={{ maxWidth: 800, margin: '0 auto' }}>
      <h1 className="page-title">Relatorios</h1>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 16, marginBottom: 20 }}>
        <Card style={{ textAlign: 'center' }}>
          <div style={{ fontSize: 24, fontWeight: 'bold' }}>{stats.total}</div>
          <div>Total</div>
        </Card>
        <Card style={{ textAlign: 'center' }}>
          <div style={{ fontSize: 24, fontWeight: 'bold', color: 'green' }}>{stats.confirmed}</div>
          <div>Confirmados</div>
        </Card>
        <Card style={{ textAlign: 'center' }}>
          <div style={{ fontSize: 24, fontWeight: 'bold', color: 'orange' }}>{stats.pending}</div>
          <div>Pendentes</div>
        </Card>
        <Card style={{ textAlign: 'center' }}>
          <div style={{ fontSize: 24, fontWeight: 'bold', color: 'red' }}>{stats.cancelled}</div>
          <div>Cancelados</div>
        </Card>
      </div>
    </div>
  );
}

export default Reports;
